import type { Plugin, Shape } from '@servicenow/sdk-build-core'
import type { Project } from '../project'

export class Inspector {
    constructor(private readonly project: Project) {}

    inspect(shape: Shape, ...plugins: Plugin[]): void {
        for (const plugin of plugins.length > 0 ? plugins : this.project.getPlugins().toArray()) {
            try {
                plugin.inspect(shape, this.project.getContext())
            } catch (error) {
                this.project
                    .getLogger()
                    .error(`Plugin "${plugin.getName()}" failed to inspect shape "${shape.getKind()}":`, error)
            }
        }
    }
}
